# Reverse image matching: average-hash (aHash) fingerprints, Hamming distance ranking.
def ahash(pixels):
    # pixels: flat list of 64 grayscale values (8x8)
    avg = sum(pixels) / len(pixels)
    return "".join("1" if p >= avg else "0" for p in pixels)
def hamming(a, b):
    return sum(x != y for x, y in zip(a, b))
gallery = {name: ahash(px) for name, px in {'a': [200]*32 + [50]*32, 'b': [195]*32 + [55]*32, 'c': [50]*32 + [200]*32}.items()}
query_hash = ahash([200]*32 + [50]*32)
print("query hash:", query_hash)
for name, h in sorted(gallery.items(), key=lambda kv: hamming(query_hash, kv[1])):
    print(f"  {name}: hamming distance {hamming(query_hash, h)}")

